-- 2) Import cases. subsystem_id intentionally stays NULL unless a verified class/subsystem mapping is selected;
-- the workbook's original subsystem label is preserved in subsystem_source_label.
INSERT INTO public.operational_case (
  case_reference, organization_id, equipment_class_id, subsystem_source_label, component_name, equipment_model_id,
  plant_facility, production_line, symptom_category, symptom_text, symptom_structured, operating_status, symptom_frequency,
  severity_proposed, primary_suspected_cause, alternative_causes, failure_mechanism, differential_diagnosis,
  corrective_action_text, required_spares_text, post_repair_verification, acceptance_criteria, recurrence_prevention, early_warning,
  case_origin, evidence_type, source_reliability, is_synthetic, model_is_illustrative, needs_depth_expansion, case_status, retrieval_eligibility
)
SELECT v.case_reference,
       'b2a7dce7-b449-4381-ba3b-b520f2c88c2e'::uuid,
       v.equipment_class_id, v.subsystem_source_label, v.component_name, em.equipment_model_id,
       v.plant_facility, v.production_line, v.symptom_category, v.symptom_text, v.symptom_structured, v.operating_status, v.symptom_frequency,
       v.severity_proposed, v.primary_suspected_cause, v.alternative_causes, v.failure_mechanism, v.differential_diagnosis,
       v.corrective_action_text, v.required_spares_text, v.post_repair_verification, v.acceptance_criteria, v.recurrence_prevention, v.early_warning,
       v.case_origin, v.evidence_type, v.source_reliability, TRUE, TRUE, v.needs_depth_expansion, 'DRAFT', 'demo_only_until_expert_review'
FROM (VALUES
  ('CASE-PUMP-001', 'EQ-PUMP', 'Bearing Assembly', 'Rolling Element Bearing', 'Kirloskar DB-100', 'Utility Plant C', 'Cooling Water Circuit', 'Noise/Vibration/Temperature', 'Pump start hone ke 20-25 min baad drive-end bearing housing ke paas ghurr-ghurr awaaz aati hai aur vibration badh jaati hai. Bearing side haath se (door se, safe hone par) normal se zyada garam lagti hai. Discharge pressure normal hai. Pichle mahine barish ke baad pump house me paani aaya tha.', 'Progressive DE-bearing noise, vibration and temperature rise after ~20-25 min run; hydraulic performance normal; recent water/dust exposure of bearing housing.', 'Running, normal duty point (illustrative; no recorded readings)', 'Continuous after warm-up; worsening over days (illustrative)', 'Medium-High', 'Grease contaminated by water/dust leading to spalling of DE bearing raceway (suspected, unconfirmed).', 'Misalignment; over/under-greasing; cavitation; looseness; bearing housing seal failure.', 'Contaminant breaks lubricant film; metal-to-metal contact causes surface fatigue, spalling and rising friction heat.', 'Misalignment: 2x running-speed and axial vibration; Cavitation: broadband high-frequency noise varying with suction conditions; Looseness: harmonics, phase differences; Seal failure: leakage visible. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'Isolate (LOTO), drain/depressurise, remove coupling guard and coupling, replace DE bearing set, inspect shaft journal/housing fits, clean housing, refill with OEM-specified lubricant, re-align, reinstall guard. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Rolling element bearing set; bearing housing lip seals/isolators; lubricant per OEM; gaskets as required (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Correct lubricant type/quantity; protect housing from water; condition monitoring (vibration, temperature); relubrication interval per OEM. Intervals: per OEM; none invented here.', 'Rising temperature trend; high-frequency vibration; grease discolouration.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-002', 'EQ-PUMP', 'Mechanical Seal', 'Seal Faces (Rotating / Stationary)', 'KSB MegaCPK', 'Utility Plant B', 'Chemical Dosing Line', 'Leakage', 'Pump chalu karne ke baad shaft ke paas se paani tapakna shuru hua, ab har kuch second me boondh gir rahi hai aur baseplate geeli ho gayi. Pump pichle hafte tank khali hone par kuch der dry chala tha. Awaaz normal hai, pressure thoda kam hai.', 'Leakage at seal/gland area, drip rate increasing; history of start-up/dry-run event; pressure slightly reduced.', 'Running (illustrative; no recorded readings)', 'Continuous since start-up (illustrative)', 'Medium', 'Seal faces worn/damaged by dry running at start-up (suspected, unconfirmed).', 'Elastomer damage; shaft deflection; flush-line fault; wrong seal installation; pressure/temperature beyond seal rating.', 'Without fluid film, lapped faces overheat, crack or wear, so face contact is lost and fluid escapes.', 'Bearing/shaft deflection: vibration rise; Elastomer leak: leakage between sleeve and seal; Gland packing leak: adjustable and different drip pattern. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'With supervisor approval and LOTO: isolate, depressurise, drain; remove seal; inspect shaft sleeve and faces; fit new seal per OEM/API 682 practice; restore flush; prove no leakage under controlled start. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Mechanical seal cartridge or face set; elastomers/O-rings; shaft sleeve; gaskets (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Prime/vent before start; dry-run protection; maintain flush plan; OEM seal selection for fluid. Intervals: per OEM; none invented here.', 'Increasing drip rate; seal-housing temperature rise; crystallised product.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-003', 'EQ-PUMP', 'Drive Train', 'Flexible Coupling', 'Grundfos CR-32', 'Utility Plant C', 'Cooling Water Circuit', 'Noise/Vibration', 'Motor badalne ke baad se pump me vibration zyada hai, khaaskar coupling ke paas. Halki thak-thak awaaz aati hai aur bearing garam hoti hai. Flow aur pressure normal hain, lekin vibration load badhne par aur noticeable hota hai.', 'Vibration at coupling end rising since motor replacement; elevated bearing temperature; hydraulic parameters normal.', 'Running, load-sensitive (illustrative; no recorded readings)', 'Continuous, since motor change (illustrative)', 'Medium', 'Angular/parallel shaft misalignment after motor replacement (suspected, unconfirmed).', 'Soft foot; pipe strain; coupling element wear; bearing damage; impeller imbalance.', 'Misalignment imposes cyclic radial/axial loads each revolution, raising vibration and bearing/seal stress.', 'Bearing defect: high-frequency content; Imbalance: 1x radial, no axial; Cavitation: broadband and pressure fluctuation. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: isolate, remove guard, check soft foot, correct alignment with laser/dial indicator to OEM tolerance, recheck pipe strain, refit guard, verify vibration. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Shims; coupling element if worn; foundation bolt set (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Alignment check after every drive removal; soft-foot check; pipe support. Intervals: per OEM; none invented here.', 'Rising 1x/2x amplitude; coupling-end heat; coupling dust.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-004', 'EQ-PUMP', 'Suction Line', 'Suction Strainer', 'Kirloskar DB-100', 'Utility Plant B', 'Cooling Water Circuit', 'Performance', 'Discharge pressure dheere dheere kam ho raha hai aur flow kam lag raha hai. Suction side ka vacuum gauge normal se zyada vacuum dikha raha hai. Pump me halki crackling awaaz bhi kabhi kabhi aati hai. Strainer pichli baar kaafi pehle saaf hua tha.', 'Gradual loss of discharge pressure and flow; high suction vacuum; intermittent crackling noise.', 'Running (illustrative; no recorded readings)', 'Progressive over days (illustrative)', 'Medium', 'Partially blocked suction strainer (suspected, unconfirmed).', 'Cavitation from other causes; loss of prime; impeller wear; closed suction valve.', 'Debris on strainer raises suction losses, lowering NPSH available and delivered head.', 'Impeller wear: suction normal but head low; Prime loss: no flow; Valve closed: vacuum high but strainer ΔP normal. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: isolate suction/discharge, drain, open strainer, clean/replace element, inspect for debris source, reinstall, vent and restart under supervision. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Strainer basket/element; gasket (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Scheduled strainer cleaning by ΔP trend; tank housekeeping. Intervals: per OEM; none invented here.', 'Rising suction vacuum; crackling noise.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-005', 'EQ-PUMP', 'Hydraulic End', 'Impeller', 'Kirloskar DB-100', 'Utility Plant A', 'Chemical Dosing Line', 'Noise/Performance', 'Pump me kankar/bajri chalne jaisi crackling awaaz aa rahi hai, discharge pressure oscillate kar raha hai aur vibration bhi hai. Suction line me valve kuch band kiya gaya tha. Awaaz flow badhane par thodi badal jaati hai.', 'Gravel-like crackling noise; fluctuating discharge pressure; vibration; started after suction throttling.', 'Running (illustrative; no recorded readings)', 'Continuous, flow-dependent (illustrative)', 'High', 'Restricted suction flow giving inadequate NPSH available (suspected, unconfirmed).', 'Strainer blockage; high fluid temperature; air entrainment; low-flow recirculation; bearing damage.', 'Local pressure falls below vapour pressure; vapour bubbles collapse at impeller causing noise, pitting and head loss.', 'Bearing defect: discrete frequencies, no pressure swing; Recirculation: occurs at low flow; Air ingress: affected by gland/joint. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: correct suction restriction, inspect impeller, replace if eroded, review NPSH margin per ANSI/HI 9.6.1. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Impeller; wear rings; gaskets (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Maintain NPSH margin; avoid throttling suction; monitor suction pressure. Intervals: per OEM; none invented here.', 'Pressure oscillation; crackling noise.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-006', 'EQ-PUMP', 'Mechanical Seal', 'Seal Faces (Rotating / Stationary)', 'Ebara 3M Series', 'Utility Plant A', 'Chilled Water Secondary Loop', 'Leakage', 'Seal housing ke nichse halka seepage hai jo pump band hone ke baad bhi chalta rehta hai. Pump pehle chemical dose line ke saath chal raha tha aur fluid temperature process change ke baad badh gaya. Leak steady hai, shor normal hai.', 'Steady seepage at seal that continues at standstill; recent fluid chemistry/temperature change; no abnormal vibration.', 'Running and standstill (illustrative; no recorded readings)', 'Continuous (illustrative)', 'Medium', 'Secondary sealing element (O-ring/elastomer) degraded by temperature or chemical incompatibility (suspected, unconfirmed).', 'Cracked seal face; sleeve damage; gasket leak; casing joint leak.', 'Incompatible fluid or heat hardens/swells elastomer so static sealing is lost even with faces intact.', 'Face wear: leak mainly when running; Joint leak: leakage between flanges; Sleeve fretting: groove on sleeve at inspection. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: isolate, depressurise, drain, replace seal with elastomer rated for fluid/temperature per OEM, leak-test. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'O-rings/elastomers in compatible material; seal cartridge if damaged (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Elastomer selection per OEM; management of change for process shifts. Intervals: per OEM; none invented here.', 'Steady seepage at standstill.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-007', 'EQ-PUMP', 'Bearing Assembly', 'Rolling Element Bearing', 'Flowserve Mark 3', 'Utility Plant B', 'Chilled Water Secondary Loop', 'Temperature', 'Bearing housing aur casing ke paas garmi zyada hai, halki zyada awaaz aa rahi hai. Oil sight glass me level neeche dikh raha hai aur oil kaala lag raha hai. Pump normal flow par chal raha hai.', 'Elevated bearing-housing/casing temperature, increased noise; low and dark oil in sight glass; flow normal.', 'Running (illustrative; no recorded readings)', 'Continuous, worsening (illustrative)', 'Medium-High', 'Insufficient oil in oil-lubricated bearing sump (suspected, unconfirmed).', 'Contaminated oil; excessive oil; misalignment; bearing damage; cooling problem.', 'Low oil reduces film and cooling, raising bearing temperature and wear.', 'Over-lubrication: heat with level high; Misalignment: 1x/2x vibration; Cooling fault: both sides heat. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: drain oil, flush, inspect bearing, replace if damaged, refill to correct level with OEM-specified oil. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Bearing set; oil; gaskets; oiler/level glass (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Oil-level checks; oil analysis; leakage repair. Intervals: per OEM; none invented here.', 'Level drop; oil darkening.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-008', 'EQ-PUMP', 'Suction and Priming', 'Suction Line Joints and Gland Seal Interface', 'Goulds 3196', 'Utility Plant A', 'Raw Water Intake', 'Performance', 'Motor chal raha hai lekin pump pani nahi de raha. Discharge gauge zero ke aas-paas hai aur pump casing me hawa ki awaaz lag rahi hai. Pump pichle shutdown ke baad restart kiya gaya aur foot valve ka condition shak me hai.', 'Motor running, no discharge flow, near-zero discharge pressure, air noise; restart after shutdown, foot valve suspect.', 'Running, no flow (illustrative; no recorded readings)', 'Since restart (illustrative)', 'High', 'Loss of pump prime (suspected, unconfirmed).', 'Closed suction valve; blocked strainer; wrong rotation; discharge valve closed.', 'Air in casing prevents impeller developing suction.', 'Wrong rotation: flow weak but present; Blocked strainer: high vacuum; Closed discharge: pressure high. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: stop, vent and prime, repair foot valve/suction joint, restart under supervision. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Foot valve; gaskets; priming accessories (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Priming checklist; foot valve inspection. Intervals: per OEM; none invented here.', 'Air noise; low current.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-009', 'EQ-PUMP', 'Bearing Assembly', 'Bearing Housing Isolators / Lip Seals', 'Goulds 3196', 'Utility Plant A', 'Chemical Dosing Line', 'Recurring failure', 'Is pump ke bearing baar baar kharab ho rahe hain, teen mahine me do baar badalna pada. Housing ke andar grease me paani/dhool mili. Shaft ke paas bearing cover se lip seal ghisa hua dikha. Har baar naye bearing ke baad kuch hafte theek chalta hai.', 'Repeated bearing replacements; contaminated grease; worn bearing housing lip seal; recurrence within weeks.', 'Running (illustrative; no recorded readings)', 'Recurring (months) (illustrative)', 'High', 'Failed housing lip seals/isolators admitting water and dust that contaminate lubricant (suspected, unconfirmed).', 'Misalignment; pipe strain; soft foot; over-greasing; wrong lubricant.', 'Contaminant ingress degrades film and causes spalling; recurrence persists because the ingress path is not corrected.', 'Misalignment: 2x and axial vibration; Looseness: harmonics; Lubricant error: no contamination. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: replace bearings and housing seals/isolators, clean housing, check shaft finish and alignment, protect from washdown. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Bearing set; lip seals/isolators; shaft sleeve if scored (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Upgrade bearing protection; root cause review of each failure; correct lubrication. Intervals: per OEM; none invented here.', 'Early life vibration rise.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-010', 'EQ-PUMP', 'Impeller and casing', NULL, 'Grundfos CR-32', 'Utility Plant A', 'Raw Water Intake', 'Noise', 'Pump se rukh rukh ke khat-khat/rattling awaaz aa rahi hai aur flow kabhi kam ho jaata hai. Pichle repair ke baad tank me kuch kapda/plastic ke tukde mile the. Awaaz bina kisi pattern ke aati-jaati hai.', 'Intermittent rattling and flow dips; debris found in tank previously.', 'Running (illustrative; no recorded readings)', 'Intermittent (illustrative)', 'Medium-High', 'Foreign material lodged in or near impeller, partially blocking vane passage (suspected, unconfirmed).', 'Cavitation; bearing damage; coupling looseness; wear ring rub.', 'Debris blocks/impacts impeller vanes causing imbalance, noise and flow reduction.', 'Cavitation: broadband; Bearing: constant tonal; Coupling: torque-related. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: open casing, remove debris, inspect impeller and wear rings, repair/replace, restore screens. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Impeller if damaged; wear rings; gaskets (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Screening; housekeeping; debris control during maintenance. Intervals: per OEM; none invented here.', 'Intermittent flow dips.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-011', 'EQ-PUMP', 'Impeller and drive assembly', NULL, 'Flowserve Mark 3', 'Utility Plant B', 'Chilled Water Secondary Loop', 'Performance/Energy', 'Motor ka current normal se zyada aa raha hai aur bijli ki khapat badh gayi hai. Pump zyada flow de raha hai kyunki discharge valve kaafi khula hua hai. Pressure kam hai lekin motor garam ho raha hai.', 'High motor current/energy use; high flow, low head with open discharge valve; motor warming.', 'Running, high flow (illustrative; no recorded readings)', 'Continuous (illustrative)', 'Medium', 'Pump operating far right of its duty point (high-flow runout) (suspected, unconfirmed).', 'Internal rub; mechanical drag; motor fault; wrong impeller trim.', 'At high flow, power demand rises and head falls; motor loads toward overload.', 'Mechanical drag: noise and vibration; Motor fault: unbalanced current. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval where intrusive: adjust system/throttle properly, check impeller trim, inspect for rub. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Impeller (if wrong trim); wear rings (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Operate near BEP; review system changes. Intervals: per OEM; none invented here.', 'Rising kWh per m³.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-012', 'EQ-PUMP', 'Motor protection and pump system', NULL, 'Grundfos CR-32', 'Utility Plant C', 'Raw Water Intake', 'Protection trips', 'Pump production ke beech me achanak trip ho jaata hai aur overload relay lagta hai. Restart ke baad kuch der chalta hai phir dobara trip. Gland/bearing se halki garmi aur bind hone jaisi awaaz lagti hai.', 'Unexpected trips with overload relay indication; restarts run briefly then trip; warm bearing/gland and binding sound.', 'Running/trip (illustrative; no recorded readings)', 'Repeated during operation (illustrative)', 'High', 'Mechanical overload from abnormal operating conditions or mechanical binding (suspected, unconfirmed).', 'Single phasing; wrong relay setting; motor fault; high flow; seal drag.', 'Increased shaft torque raises current until thermal overload operates.', 'Single phasing: current imbalance; Relay setting error: normal current; Flow runout: high flow. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: locate binding source, inspect seal/bearing/impeller, verify settings with qualified electrician. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Bearing/seal as required (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Trend current; confirm settings; inspect after trips. Intervals: per OEM; none invented here.', 'Rising current.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-013', 'EQ-PUMP', 'Hydraulic End', 'Impeller and Wear Rings', 'Flowserve Mark 3', 'Utility Plant A', 'Chilled Water Secondary Loop', 'Performance', 'Pump ka head aur flow pehle se kam hai, jabki suction aur motor current normal hain. Discharge pressure rated se neeche aa raha hai. Pump kaafi saalon se bina internal overhaul ke chal raha hai aur fluid me ret/silt aata hai.', 'Reduced head/flow versus baseline; normal suction and current; long run without overhaul; abrasive fluid.', 'Running (illustrative; no recorded readings)', 'Gradual over months (illustrative)', 'Medium', 'Wear-ring clearance increased by abrasive wear causing internal recirculation (suspected, unconfirmed).', 'Impeller erosion; strainer blockage; speed loss; air ingress.', 'Larger clearance lets high-pressure fluid leak back to suction, reducing delivered head/flow.', 'Strainer: suction vacuum high; Impeller erosion: visible; Speed: slower. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: open pump, measure ring clearances, replace rings (and impeller if needed) to OEM clearances. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Wear rings; impeller; gaskets (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Performance trending; filtration. Intervals: per OEM; none invented here.', 'Head decline.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-014', 'EQ-PUMP', 'Drive Train', 'Flexible Coupling', 'KSB MegaCPK', 'Utility Plant C', 'Boiler Feedwater Line', 'Noise/Vibration', 'Pump start aur stop par jhatka sa lagta hai aur coupling ke paas khat-khat awaaz aati hai. Coupling guard ke andar se rubber ki dhool nikal rahi hai. Load par vibration thodi badhti hai.', 'Jerk on start/stop; clatter at coupling; rubber dust visible; vibration up under load.', 'Running (illustrative; no recorded readings)', 'Continuous (illustrative)', 'Medium', 'Flexible coupling element degraded or worn (suspected, unconfirmed).', 'Misalignment; loose hubs; keyway wear; bearing damage.', 'Worn element permits backlash and uneven torque transfer.', 'Misalignment: steady 1x/2x; Bearing: high frequency. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: remove guard, inspect hubs/element, replace element and check keys, align, refit. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Coupling element; keys; hub bolts (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Inspect coupling periodically; alignment. Intervals: per OEM; none invented here.', 'Dust; clatter.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-015', 'EQ-PUMP', 'Hydraulic End', 'Impeller and Casing Volute', 'KSB MegaCPK', 'Utility Plant A', 'Cooling Water Circuit', 'Vibration', 'Jab discharge valve zyada band karke flow kam rakhte hain tab pump me vibration aur shaft ke paas seal/bearing ki taklif badhti hai. Casing ke andar se ghoomne jaisi awaaz aati hai. Normal flow par vibration kam ho jaata hai.', 'Vibration and noise increase at reduced flow, easing at normal flow; seal/bearing stress.', 'Running throttled (illustrative; no recorded readings)', 'With low flow (illustrative)', 'Medium-High', 'Low-flow internal recirculation causing radial loads and shaft deflection (suspected, unconfirmed).', 'Cavitation; misalignment; bearing wear.', 'At low flow, flow separation creates unbalanced radial thrust deflecting the shaft.', 'Cavitation: depends on suction; Misalignment: independent of flow. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval for intrusive checks: add bypass/minimum-flow, check impeller/shaft. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Seal; bearings; shaft if damaged (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Respect OEM minimum flow. Intervals: per OEM; none invented here.', 'Low-flow noise.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-016', 'EQ-PUMP', 'Suction and Priming', 'Suction Line Joints and Gland Seal Interface', 'Grundfos CR-32', 'Utility Plant A', 'Chemical Dosing Line', 'Performance', 'Flow aur pressure ka needle upar-niche hota rehta hai, kabhi kabhi gland ke paas se hawa ke bulbule ya halki hiss. Tank me bulbule bhi dikhte hain. Pump bilkul band nahi hota lekin delivery uneven hai.', 'Fluctuating flow/pressure, air bubbles and hissing at gland/joints; no total flow loss.', 'Running (illustrative; no recorded readings)', 'Intermittent (illustrative)', 'Medium', 'Air ingress via suction joint or gland seal interface (suspected, unconfirmed).', 'Cavitation; blocked strainer; vortexing.', 'Air enters suction and entrains, reducing head and causing pulsation.', 'Cavitation: crackling; Prime loss: no flow. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: replace joint gaskets/gland, retighten, vent. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Gaskets; gland packing/seal (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Flange inspection. Intervals: per OEM; none invented here.', 'Pressure oscillation.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-PUMP-017', 'EQ-PUMP', 'Shaft Assembly', 'Pump Shaft', 'Goulds 3196', 'Utility Plant B', 'Raw Water Intake', 'Performance/Noise', 'Pehle kaafi din se vibration aur bearing area me issue tha, ab achanak pump flow nahi de raha lekin motor halka load par chal raha hai. Coupling ke paas se alag awaaz thi aur phir band ho gayi.', 'Long-running vibration then sudden loss of delivery with light motor load; abrupt change in noise.', 'Running, no flow (illustrative; no recorded readings)', 'Sudden after chronic vibration (illustrative)', 'Critical', 'Pump shaft fatigue fracture (suspected, unconfirmed).', 'Coupling failure; impeller loose; loss of prime.', 'Cyclic bending stress initiates cracks that propagate until fracture.', 'Coupling failure: shaft intact; Prime loss: shaft turns. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: dismantle, replace shaft, inspect bearings/seals/impeller, correct root cause (misalignment/recirculation). Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Shaft; bearings; seal; impeller key (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Address vibration early. Intervals: per OEM; none invented here.', 'Chronic vibration.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-MOT-001', 'EQ-MOTOR', 'Stator & Windings', 'Winding Insulation (Copper Magnet Wire and Varnish)', 'Siemens 1LE1', 'Utility Plant B', 'Raw Material Processing Line', 'Electrical/Protection', 'Motor start karte hi kuch second me trip ho jaata hai aur terminal box ke paas jalne ki smell aati hai. Motor kaafi garam rehta tha aur barish me pani aata tha. Overcurrent/earth fault indication aa raha hai.', 'Trips within seconds of start; burning smell; history of overheating and moisture; overcurrent/earth fault indication.', 'Start/trip (illustrative; no recorded readings)', 'Every start attempt (illustrative)', 'High', 'Winding turn-to-turn short from chronic overheating and moisture (suspected, unconfirmed).', 'Terminal fault; phase-to-ground fault; supply fault; locked rotor.', 'Insulation ageing under heat/moisture breaks down between turns, creating shorted loops and heating.', 'Supply fault: phase voltage abnormal; Locked rotor: hum, high current; Terminal fault: local damage. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: isolate, test/inspect, rewind or replace motor (qualified shop), dry and varnish if applicable. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Rewind kit/motor; terminal gaskets (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Keep motor dry/clean; periodic insulation tests. Intervals: per OEM; none invented here.', 'Falling IR; heating.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-MOT-002', 'EQ-MOTOR', 'Bearing Assembly', 'Drive-End Bearing and Grease', 'Marathon Blue Max', 'Utility Plant B', 'Main Conveyor Drive', 'Temperature/Noise', 'Motor ka peeche (non-drive end) wala bearing bahut garam hai aur ghurr-ghurr awaaz aa rahi hai. Pichle maintenance me bahut zyada grease bhari gayi thi aur alag brand ka grease use hua. Grease relief se bahar nikal rahi hai.', 'Hot rear bearing with growling noise; recent excess/incompatible grease; grease extruding.', 'Running (illustrative; no recorded readings)', 'Continuous after greasing (illustrative)', 'Medium-High', 'Over-greasing with incompatible grease (suspected, unconfirmed).', 'Misalignment; bearing wear; electrical discharge damage; cooling issue.', 'Excess grease causes churning heat; incompatible grease degrades film.', 'Misalignment: 1x/2x; EDM: fluting; Lubrication-starved: dry grease. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: purge old grease, inspect/replace bearing, refill correct grease and quantity per OEM. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Bearings; grease per OEM (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Grease procedure; compatibility. Intervals: per OEM; none invented here.', 'Temperature trend.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-MOT-003', 'EQ-MOTOR', 'Cooling System', 'Cooling Fan and Cowl', 'Crompton Greaves IE3', 'Utility Plant A', 'Compressed Air Line', 'Temperature', 'Motor body bahut garam hai, thermal protection warning aa raha hai. Fan cowl ke jaali me dhool/ruii jam gayi hai aur motor dhool bhare area me hai. Load normal hai.', 'High body/winding temperature and thermal warnings; dust-clogged cowl; normal load.', 'Running (illustrative; no recorded readings)', 'Continuous, worsening (illustrative)', 'Medium-High', 'Blocked cooling air passages (suspected, unconfirmed).', 'Overload; voltage problem; fan damage; high ambient.', 'Reduced airflow lowers heat removal so winding temperature rises.', 'Overload: high current; Voltage fault: current/voltage abnormal. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: clean fins/cowl, inspect fan, restore airflow. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Fan/cowl if damaged (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Cleaning schedule. Intervals: per OEM; none invented here.', 'Temperature creep.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-MOT-004', 'EQ-MOTOR', 'Starter circuit and motor supply', NULL, 'Schneider Process Motors', 'Utility Plant A', 'Exhaust Blower Drive', 'Starting', 'Start button dabane par motor nahi ghoomta aur contactor chalta hai phir overload relay trip dikhta hai. Pehle thodi garam chal raha tha. Reset karne par kuch der baad phir trip.', 'No rotation on start; contactor operates then overload trips; recent warm running.', 'Start attempt (illustrative; no recorded readings)', 'Repeated (illustrative)', 'Medium', 'Overload relay tripped by sustained overcurrent or setting issue (suspected, unconfirmed).', 'Supply fault; jammed load; winding fault; control circuit fault.', 'Thermal element operates after prolonged high current.', 'Single-phasing: unbalanced; Jam: high current/hum. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: check for jam, verify relay setting with electrician, repair root cause. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Overload relay if faulty (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Verify settings. Intervals: per OEM; none invented here.', 'Repeated nuisance trips.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-MOT-005', 'EQ-MOTOR', 'Rotor Assembly', 'Rotor Core and Shaft', 'Siemens 1LE1', 'Utility Plant C', 'Compressed Air Line', 'Vibration', 'Motor me vibration badh gayi hai aur halki mechanical awaaz hai. Coupling disconnect karne par bhi vibration rehti hai. Speed ke saath vibration badhta hai.', 'Increased vibration persisting uncoupled; speed-proportional.', 'Running (illustrative; no recorded readings)', 'Continuous (illustrative)', 'Medium', 'Rotor imbalance (suspected, unconfirmed).', 'Soft foot; misalignment; bearing damage; bent shaft.', 'Uneven mass produces 1x centrifugal force.', 'Misalignment: axial; Looseness: harmonics. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: balance rotor (qualified shop), inspect shaft. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Balance weights; bearings (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Balance after repair. Intervals: per OEM; none invented here.', '1x rise.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-MOT-006', 'EQ-MOTOR', 'Bearing Assembly', 'Drive-End Bearing and Grease', 'Siemens 1LE1', 'Utility Plant B', 'Main Conveyor Drive', 'Temperature/Noise', 'Motor ka drive-end bearing garam ho raha hai, grease sukhi aur kaali dikhti hai aur relubrication kaafi time se nahi hui. Garmi ke mausam me aur badh jaata hai. Halki squeal awaaz hai.', 'DE bearing hot; hardened dark grease; overdue relubrication; worse in hot weather; squeal.', 'Running (illustrative; no recorded readings)', 'Continuous (illustrative)', 'Medium-High', 'Grease degradation/under-lubrication from overdue relubrication and high ambient (suspected, unconfirmed).', 'Over-greasing; misalignment; bearing wear.', 'Dry degraded grease increases friction heat.', 'Over-greasing: grease extruded; EDM: fluting. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: regrease/replace bearing per OEM. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Bearing; grease (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Relubrication schedule. Intervals: per OEM; none invented here.', 'Temp trend.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-MOT-007', 'EQ-MOTOR', 'Motor and overload protection', NULL, 'WEG W22 Premium', 'Utility Plant B', 'Exhaust Blower Drive', 'Protection trips', 'Production ke time motor baar baar overload par trip hota hai, line load badhne par zyada. Current nameplate se upar dikhta hai. Motor garam hai.', 'Repeated overload trips at higher production load; current above nameplate; warm.', 'Running/trip (illustrative; no recorded readings)', 'Repeated (illustrative)', 'High', 'Excessive driven-equipment load (suspected, unconfirmed).', 'Voltage drop; mechanical binding; bearing issue; wrong setting.', 'Load torque exceeds rating, raising current.', 'Voltage low: current high with low volts; Drag: noise. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: reduce load/repair driven equipment, verify protection. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'As required (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Load review. Intervals: per OEM; none invented here.', 'Rising current.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-MOT-008', 'EQ-MOTOR', 'Power Supply', 'Supply Phase Conductors, Fuses and Contactor', 'Crompton Greaves IE3', 'Utility Plant A', 'Compressed Air Line', 'Starting/Electrical', 'Motor hum karta hai lekin ghoomta nahi, ya ghoomne par bahut dheere aur garam ho jaata hai. Ek phase ka fuse udha hua lagta hai. Motor se zor ki bhanbhanahat hai.', 'Humming without rotation (or weak rotation) and heating; one fuse suspect.', 'Start attempt (illustrative; no recorded readings)', 'Every start (illustrative)', 'High', 'Loss of one supply phase (single-phasing) (suspected, unconfirmed).', 'Locked rotor; winding open; contactor fault.', 'Without third phase, no rotating field.', 'Locked rotor: all phases high current. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: repair supply, replace fuse/contactor, test. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Fuse; contactor (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Phase-loss protection. Intervals: per OEM; none invented here.', 'Fuse faults.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
  ('CASE-MOT-009', 'EQ-MOTOR', 'Stator & Windings', 'Winding Insulation (Copper Magnet Wire and Varnish)', 'Schneider Process Motors', 'Utility Plant A', 'Exhaust Blower Drive', 'Electrical', 'Insulation monitoring alarm aa raha hai aur megger reading pehle se kam aati hai, khaaskar monsoon me. Motor chal raha hai lekin pani ka nishaan terminal box me hai.', 'Insulation alarm; falling IR trend, seasonal; moisture marks in terminal box.', 'Running/idle (illustrative; no recorded readings)', 'Seasonal (illustrative)', 'Medium', 'Moisture ingress into windings (suspected, unconfirmed).', 'Contamination; ageing; cable fault.', 'Moisture creates leakage paths.', 'Contamination: surface; Ageing: persistent. Diagnosis remains inconclusive if Tier 2 results lie within OEM/site baseline or point equally to two causes; then escalate to supervisor/OEM.', 'LOTO and supervisor approval: dry out and retest; repair seals. Requires supervisor approval and LOTO before work. Tools/expertise: qualified maintenance technician with OEM procedure.', 'Seals; heater (part numbers/compatibility must come from OEM parts list)', 'Repeat the same Tier 2 measurements after repair; confirm original symptom absent; controlled restart under supervision; monitor for recurrence.', 'Readings within OEM specification or approved site baseline (source: OEM manual / site standard - not stated in this workbook).', 'Heaters; sealing. Intervals: per OEM; none invented here.', 'IR trend.', 'Synthetic Scenario', 'Engineering interpretation (no field record; no OEM manual consulted)', 'D', FALSE),
