-- Verification: expected total_cases=50 for a fresh import into an empty operational_case table.
SELECT case_status, retrieval_eligibility, is_synthetic, model_is_illustrative, COUNT(*) AS total_cases
FROM public.operational_case
WHERE organization_id = 'b2a7dce7-b449-4381-ba3b-b520f2c88c2e'::uuid
GROUP BY case_status, retrieval_eligibility, is_synthetic, model_is_illustrative
ORDER BY case_status;
